<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue'
import WorkspaceShell from '../components/WorkspaceShell.vue'
import { adminApi } from '../api/admin'
import type { ContentReport } from '../api/admin'
import { formatTime } from '../api/creator'
import { useStudioError } from '../composables/useStudioError'
const explain = useStudioError(); const items = ref<ContentReport[]>([]); const page = ref(1); const total = ref(0); const status = ref('OPEN'); const loading = ref(false); const busy = ref(false); const error = ref(''); const notice = ref('')
let request: AbortController | undefined; let stopped = false
async function load(next = page.value) { request?.abort(); const c = new AbortController(); request = c; loading.value = true; error.value = ''; try { const r = await adminApi.reports(status.value, next, c.signal); if (!stopped && !c.signal.aborted) { items.value = r.items; page.value = r.page; total.value = r.total } } catch (f) { if (!stopped && !c.signal.aborted) error.value = explain(f) } finally { if (!stopped && !c.signal.aborted) loading.value = false } }
async function resolve(item: ContentReport, action: 'DISMISS' | 'REMOVE') { if (busy.value) return; const reason = action === 'REMOVE' ? window.prompt('删除目标原因（可选）')?.trim() ?? '' : window.prompt('驳回举报原因（可选）')?.trim() ?? ''; if (!window.confirm(action === 'REMOVE' ? '删除被举报内容？' : '驳回这条举报？')) return; busy.value = true; error.value = ''; notice.value = ''; try { await adminApi.resolveReport(item, action, reason); if (!stopped) { notice.value = action === 'REMOVE' ? '已删除目标。' : '已驳回举报。'; await load() } } catch (f) { if (!stopped) error.value = explain(f) } finally { if (!stopped) busy.value = false } }
function switchStatus(s: string) { status.value = s; void load(1) }
onMounted(() => { void load() }); onBeforeUnmount(() => { stopped = true; request?.abort() })
</script>
<template><WorkspaceShell><div class="studio-heading"><div><p class="eyebrow">FRAME ROOM / REPORTS</p><h1>举报处理</h1><p class="muted">查看举报，驳回或删除目标内容。</p></div><el-button :loading="loading" @click="load()">刷新</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false" role="alert"/><p v-if="notice" class="muted" role="status">{{ notice }}</p><div class="inline-actions"><el-button :type="status==='OPEN'?'primary':'default'" @click="switchStatus('OPEN')">待处理</el-button><el-button :type="status==='DISMISSED'?'primary':'default'" @click="switchStatus('DISMISSED')">已驳回</el-button><el-button :type="status==='REMOVED'?'primary':'default'" @click="switchStatus('REMOVED')">已删除</el-button></div><section class="studio-panel" :aria-busy="loading"><p v-if="loading" class="muted">正在加载举报…</p><article v-for="item in items" :key="item.id" class="history-item"><div class="section-heading"><strong>#{{ item.id }} · {{ item.targetType }} #{{ item.targetId }}</strong><time>{{ formatTime(item.createdAt) }}</time></div><p>举报人：{{ item.reporterName }}</p><p class="history-reason">{{ item.reason }}</p><div class="inline-actions" v-if="item.status==='OPEN'"><el-button @click="resolve(item,'DISMISS')">驳回</el-button><el-button type="danger" :disabled="busy" @click="resolve(item,'REMOVE')">删除目标</el-button></div><p v-else class="muted">处理结果：{{ item.status }}</p></article><p v-if="!loading && !items.length" class="empty-state">没有举报。</p><div class="page-controls"><el-button :disabled="loading || page<=1" @click="load(page-1)">上一页</el-button><span>第 {{ page }} 页</span><el-button :disabled="loading || page*20>=total || page>=1000" @click="load(page+1)">下一页</el-button></div></section></WorkspaceShell></template>
